using System.Collections.Generic;
using UnityEngine;

namespace EggRescue
{
    public sealed class AudioDirector : MonoBehaviour
    {
        public static AudioDirector Instance { get; private set; }

        [SerializeField] AudioClip[] audioClips;
        [SerializeField] AudioSource sfxSource;
        [SerializeField] AudioSource bgmSource;
        [SerializeField] ParticleSystem[] particleSystems;

        AudioClip _originalBgm;
        bool _adoptedSceneBgm;
        readonly Dictionary<string, AudioClip> _byName = new Dictionary<string, AudioClip>();
        readonly Dictionary<string, ParticleSystem> _spawnedParticles = new Dictionary<string, ParticleSystem>();

        void Awake()
        {
            Instance = this;
            if (sfxSource == null) sfxSource = gameObject.AddComponent<AudioSource>();
            if (bgmSource == null) bgmSource = AdoptSceneBgmSource();
            if (bgmSource == null)
            {
                bgmSource = gameObject.AddComponent<AudioSource>();
                bgmSource.loop = true;
                bgmSource.playOnAwake = false;
            }
            RebuildMap();
            LoadEditorClipsIfNeeded();
            if (bgmSource.clip != null) _originalBgm = bgmSource.clip;
        }

        /// <summary>
        /// ???????????????? BGM AudioSource?
        /// ???????? AudioDirector ???????? BGM ????
        /// </summary>
        AudioSource AdoptSceneBgmSource()
        {
            var sources = FindObjectsOfType<AudioSource>(true);
            AudioSource best = null;
            for (var i = 0; i < sources.Length; i++)
            {
                var src = sources[i];
                if (src == null || src == sfxSource) continue;
                if (src.gameObject == gameObject) continue;
                // BGM ?????? + ????(????) + 2D?
                if (!src.loop) continue;
                if (!src.playOnAwake && !src.isPlaying) continue;
                if (src.spatialBlend > 0.5f) continue;
                if (best == null) best = src;
                else src.Stop(); // ?????????????????????
            }
            if (best != null)
            {
                _adoptedSceneBgm = true;
                Debug.Log("[AudioDirector] adopted scene BGM source: " + best.gameObject.name);
            }
            return best;
        }

        void Start()
        {
            // ????? BGM ?????????????? audio_bgm ???????????
            if (_adoptedSceneBgm && bgmSource != null && bgmSource.clip != null)
            {
                if (!bgmSource.isPlaying)
                {
                    bgmSource.loop = true;
                    bgmSource.Play();
                }
                return;
            }
            if (_byName.ContainsKey("audio_bgm"))
                PlayBGM();
            else if (_byName.ContainsKey("bgm"))
            {
                bgmSource.clip = _byName["bgm"];
                bgmSource.loop = true;
                bgmSource.Play();
                _originalBgm = bgmSource.clip;
            }
        }

        public void SetClips(AudioClip[] clips)
        {
            audioClips = clips;
            RebuildMap();
        }

        public void SetParticles(ParticleSystem[] systems)
        {
            particleSystems = systems;
        }

        void RebuildMap()
        {
            _byName.Clear();
            if (audioClips == null) return;
            for (var i = 0; i < audioClips.Length; i++)
            {
                var clip = audioClips[i];
                if (clip != null && !_byName.ContainsKey(clip.name))
                    _byName[clip.name] = clip;
            }
        }

        void LoadEditorClipsIfNeeded()
        {
            if (_byName.Count > 0) return;
#if UNITY_EDITOR
            var guids = UnityEditor.AssetDatabase.FindAssets("t:AudioClip", new[] { "Assets/Res/AudioAssets" });
            var list = new List<AudioClip>();
            for (var i = 0; i < (guids == null ? 0 : guids.Length); i++)
            {
                var path = UnityEditor.AssetDatabase.GUIDToAssetPath(guids[i]);
                var clip = UnityEditor.AssetDatabase.LoadAssetAtPath<AudioClip>(path);
                if (clip != null) list.Add(clip);
            }
            audioClips = list.ToArray();
            RebuildMap();
#endif
        }

        public static void PlayAudio(string name)
        {
            if (Instance != null) Instance.PlayOneShot(name);
        }

        public static void PlayBGM()
        {
            if (Instance == null) return;
            if (Instance._originalBgm != null)
                Instance.bgmSource.clip = Instance._originalBgm;
            else
            {
                AudioClip clip;
                if (Instance._byName.TryGetValue("audio_bgm", out clip) || Instance._byName.TryGetValue("bgm", out clip))
                    Instance.bgmSource.clip = clip;
            }
            Instance.bgmSource.loop = true;
            if (Instance.bgmSource.clip != null)
                Instance.bgmSource.Play();
        }

        public static void StopBGM()
        {
            if (Instance != null && Instance.bgmSource != null)
                Instance.bgmSource.Stop();
        }

        public static void PlayMusic(string name)
        {
            if (Instance == null) return;
            AudioClip clip;
            if (!Instance._byName.TryGetValue(name ?? "", out clip) || clip == null)
            {
                Debug.Log("[AudioDirector] missing music " + name);
                return;
            }
            Instance.bgmSource.Stop();
            Instance.bgmSource.clip = clip;
            Instance.bgmSource.loop = true;
            Instance.bgmSource.Play();
        }

        public static float GetClipLength(string name)
        {
            if (Instance == null) return 0f;
            AudioClip clip;
            if (!Instance._byName.TryGetValue(name ?? "", out clip) || clip == null) return 0f;
            return clip.length;
        }

        public static void PlayParticle(string name, Vector3 position)
        {
            if (Instance == null || string.IsNullOrEmpty(name)) return;
            var ps = Instance.ResolveParticle(name, position);
            if (ps == null) return;
            ps.transform.position = position;
            ps.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);
            ps.Play(true);
        }

        ParticleSystem ResolveParticle(string name, Vector3 position)
        {
            ParticleSystem found;
            if (_spawnedParticles.TryGetValue(name, out found) && found != null)
                return found;

            if (particleSystems != null)
            {
                for (var i = 0; i < particleSystems.Length; i++)
                {
                    var ps = particleSystems[i];
                    if (ps == null || ps.name != name) continue;
                    _spawnedParticles[name] = ps;
                    return ps;
                }
            }

            var prefab = LoadParticlePrefab(name);
            if (prefab == null)
            {
                Debug.LogWarning("[AudioDirector] missing particle " + name);
                return null;
            }

            var go = Instantiate(prefab, position, Quaternion.identity, transform);
            go.name = name;
            var spawned = go.GetComponent<ParticleSystem>();
            if (spawned == null) spawned = go.GetComponentInChildren<ParticleSystem>(true);
            if (spawned == null)
            {
                Debug.LogWarning("[AudioDirector] particle prefab has no ParticleSystem " + name);
                return null;
            }
            _spawnedParticles[name] = spawned;
            return spawned;
        }

        static GameObject LoadParticlePrefab(string name)
        {
            var catalog = Resources.Load<VfxCatalog>("VfxCatalog");
            if (catalog != null && catalog.Prefabs != null)
            {
                for (var i = 0; i < catalog.Prefabs.Length; i++)
                {
                    var prefab = catalog.Prefabs[i];
                    if (prefab != null && prefab.name == name) return prefab;
                }
            }
#if UNITY_EDITOR
            return UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Res/vfx/prefabs/" + name + ".prefab");
#else
            return null;
#endif
        }

        void PlayOneShot(string name)
        {
            AudioClip clip;
            if (!_byName.TryGetValue(name ?? "", out clip) || clip == null)
            {
                Debug.Log("[AudioDirector] missing clip " + name);
                return;
            }
            sfxSource.PlayOneShot(clip);
        }
    }
}
using TMPro;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

namespace EggRescue
{
    public sealed class GameBootstrap : MonoBehaviour
    {
        public static GameBootstrap Instance { get; private set; }
        public Transform playerSpawn;
        public GameObject playerPrefab;
        bool _booted;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
        static void AutoBoot()
        {
            if (SceneManager.GetActiveScene().name == GameSession.MenuSceneName) return;
            if (FindObjectOfType<GameBootstrap>() != null) return;
            var go = new GameObject("EggRescue_Runtime");
            go.AddComponent<GameBootstrap>();
        }

        void Awake()
        {
            Instance = this;
            DontDestroyOnLoad(gameObject);
            Boot();
        }

        public void Boot()
        {
            if (_booted) return;
            _booted = true;
            if (IsArtWalkScene())
            {
                EnsureArtWalk();
                return;
            }
            GameSettings.Load();
            GameState.LoadDefaults();
            NpcRegistry.Load();
            DialogueDatabase.LoadAll();
            CheeseRegistry.ClearPicked();
            InteractionPointVfx.ClearDiscovered();
            ClimbPathPoint.ResetPaths();
            SaveService.ClearPose();
            if (GameSession.ShouldLoadSave())
                SaveService.Load();
            GameSession.Consume();
            EnsureAudio();
            EnsureDialogue();
            EnsurePlayer();
            EnsureSystems();
            AutoWireWorld();
            DisableDouyinRuntime();
        }

        void Update()
        {
            if (IsArtWalkScene())
            {
                if (Input.GetKeyDown(KeyCode.Escape))
                    GameEvents.SetPaused(!GameEvents.Paused);
                return;
            }
            if (Input.GetKeyDown(KeyCode.F5)) SaveService.Save();
            if (Input.GetKeyDown(KeyCode.F9)) SaveService.Load();
        }

        /// <summary>
        /// 美术预览场景只保留走路和第三人称镜头，方便录视频。
        /// </summary>
        static bool IsArtWalkScene()
        {
            var name = SceneManager.GetActiveScene().name;
            return name.StartsWith("ArtTest");
        }

        void EnsureArtWalk()
        {
            GameObject player = null;
            if (PlayerController.Instance != null)
                player = PlayerController.Instance.gameObject;
            else
            {
                var existing = FindObjectOfType<PlayerController>();
                if (existing != null) player = existing.gameObject;
            }
            if (player == null)
                player = SpawnPlayer();
            player.tag = "Player";
            player.layer = 2;
            var interaction = player.GetComponent<PlayerInteraction>();
            if (interaction != null) interaction.enabled = false;
            BindCameraToPlayer(player);
        }

        void EnsureAudio()
        {
            if (AudioDirector.Instance != null) return;
            gameObject.AddComponent<AudioDirector>();
        }

        void EnsureDialogue()
        {
            if (DialogueManager.Instance != null) return;
            var existing = GameObject.Find("DialogueManager");
            if (existing != null)
            {
                var dm = existing.GetComponent<DialogueManager>();
                if (dm == null) existing.AddComponent<DialogueManager>();
                return;
            }
            var go = new GameObject("DialogueManager");
            go.AddComponent<DialogueManager>();
        }

        void EnsurePlayer()
        {
            if (PlayerController.Instance != null) return;
            var player = SpawnPlayer();
            player.tag = "Player";
            player.layer = 2;
            BindCameraToPlayer(player);
            ApplySavedPose(player);
            CreatePrompt(player.GetComponent<PlayerInteraction>());
        }

        GameObject SpawnPlayer()
        {
            Vector3 pos;
            Quaternion rot;
            ResolveSpawn(out pos, out rot);
            GameObject player;
            if (playerPrefab != null)
            {
                player = Instantiate(playerPrefab, pos, rot);
            }
            else
            {
                player = GameObject.CreatePrimitive(PrimitiveType.Capsule);
                player.name = "Player";
                var col = player.GetComponent<Collider>();
                if (col != null) col.enabled = false;
                var cc = player.AddComponent<CharacterController>();
                cc.height = 1.8f;
                cc.radius = 0.4f;
                cc.center = new Vector3(0f, 0.9f, 0f);
                player.transform.SetPositionAndRotation(pos, rot);
            }
            if (player.GetComponent<PlayerController>() == null)
                player.AddComponent<PlayerController>();
            if (player.GetComponent<PlayerInteraction>() == null)
                player.AddComponent<PlayerInteraction>();
            return player;
        }

        static void ApplySavedPose(GameObject player)
        {
            if (!SaveService.HasPose || player == null) return;
            var controller = player.GetComponent<PlayerController>();
            if (controller != null)
                controller.Teleport(SaveService.PosePosition, SaveService.PoseYaw);
            else
                player.transform.SetPositionAndRotation(SaveService.PosePosition, Quaternion.Euler(0f, SaveService.PoseYaw, 0f));
            if (ThirdPersonCamera.Instance != null)
                ThirdPersonCamera.Instance.SetView(SaveService.PoseViewYaw, SaveService.PosePitch);
        }

        static void BindCameraToPlayer(GameObject player)
        {
            var cam = ResolveMainCamera();
            if (cam == null) return;
            DisableConflictingCameraDrivers(cam.gameObject);
            var tps = cam.GetComponent<ThirdPersonCamera>();
            if (tps == null) tps = cam.gameObject.AddComponent<ThirdPersonCamera>();
            var pc = player.GetComponent<PlayerController>();
            var follow = pc != null && pc.CameraPivot != null ? pc.CameraPivot : player.transform;
            tps.SetTarget(follow);
            tps.SnapToTarget();
        }

        /// <summary>
        /// 场景相机上若残留 demo 脚本(OrbitMotion / TMP CameraController 等)，
        /// 它们会和 ThirdPersonCamera 争抢同一个 transform，表现为画面抖动。
        /// </summary>
        static void DisableConflictingCameraDrivers(GameObject camGo)
        {
            var behaviours = camGo.GetComponents<MonoBehaviour>();
            for (var i = 0; i < behaviours.Length; i++)
            {
                var mb = behaviours[i];
                if (mb == null) continue;
                var n = mb.GetType().Name;
                if (n == "ThirdPersonCamera") continue;
                if (n == "OrbitMotion" || n == "CameraController" || n == "SmoothFollow"
                    || n == "CameraFollow" || n == "CinemachineBrain")
                {
                    mb.enabled = false;
                    Debug.Log("[GameBootstrap] disabled conflicting camera driver: " + n);
                }
            }
        }

        static Camera ResolveMainCamera()
        {
            var cam = Camera.main;
            if (cam != null) return cam;
            var named = GameObject.Find("Main Camera");
            if (named != null)
            {
                cam = named.GetComponent<Camera>();
                if (cam != null)
                {
                    named.tag = "MainCamera";
                    return cam;
                }
            }
            var all = Object.FindObjectsOfType<Camera>(true);
            for (var i = 0; i < all.Length; i++)
            {
                if (all[i] != null && all[i].enabled)
                    return all[i];
            }
            return all != null && all.Length > 0 ? all[0] : null;
        }

        void ResolveSpawn(out Vector3 pos, out Quaternion rot)
        {
            if (playerSpawn == null)
            {
                var named = GameObject.Find("PlayerSpawn");
                if (named != null) playerSpawn = named.transform;
            }
            if (playerSpawn != null)
            {
                pos = playerSpawn.position;
                rot = FlattenYaw(playerSpawn.rotation);
                return;
            }
            var shufen = InteractionUtil.FindByName("淑芬1") ?? InteractionUtil.FindByName("淑芬");
            if (shufen != null)
            {
                var away = shufen.transform.forward;
                away.y = 0f;
                if (away.sqrMagnitude < 0.01f) away = Vector3.forward;
                else away.Normalize();
                pos = shufen.transform.position + away * 2.2f + Vector3.up * 0.05f;
                rot = FlattenYaw(Quaternion.LookRotation(-away, Vector3.up));
                return;
            }
            var cam = Camera.main;
            if (cam != null)
            {
                pos = cam.transform.position;
                rot = FlattenYaw(cam.transform.rotation);
                return;
            }
            pos = Vector3.up * 0.05f;
            rot = Quaternion.identity;
        }

        static Quaternion FlattenYaw(Quaternion rotation)
        {
            var forward = rotation * Vector3.forward;
            forward.y = 0f;
            if (forward.sqrMagnitude < 0.0001f) return Quaternion.identity;
            return Quaternion.LookRotation(forward.normalized, Vector3.up);
        }

        void CreatePrompt(PlayerInteraction interaction)
        {
            var canvasGo = new GameObject("InteractionPromptCanvas");
            var canvas = canvasGo.AddComponent<Canvas>();
            canvas.renderMode = RenderMode.ScreenSpaceOverlay;
            canvasGo.AddComponent<CanvasScaler>();
            canvasGo.AddComponent<GraphicRaycaster>();
            var textGo = new GameObject("Prompt");
            textGo.transform.SetParent(canvasGo.transform, false);
            var text = textGo.AddComponent<TextMeshProUGUI>();
            var font = UiFontCatalog.Load();
            if (font != null) text.font = font;
            text.fontSize = 28;
            text.alignment = TextAlignmentOptions.Bottom;
            text.color = Color.white;
            text.raycastTarget = false;
            var rt = text.rectTransform;
            rt.anchorMin = new Vector2(0.3f, 0.08f);
            rt.anchorMax = new Vector2(0.7f, 0.16f);
            rt.offsetMin = Vector2.zero;
            rt.offsetMax = Vector2.zero;
            text.gameObject.SetActive(false);
            if (interaction != null) interaction.SetPromptLabel(text);
        }

        void EnsureSystems()
        {
            if (GetComponent<PauseMenu>() == null)
                gameObject.AddComponent<PauseMenu>();
            if (FindObjectOfType<MouseBrotherShop>() == null)
                gameObject.AddComponent<MouseBrotherShop>();
            if (FindObjectOfType<CheeseRefreshManager>() == null)
                gameObject.AddComponent<CheeseRefreshManager>();
            var notebook = GameObject.Find("Notebook");
            if (notebook != null && notebook.GetComponent<BookController>() == null)
                notebook.AddComponent<BookController>();
            if (notebook != null)
            {
                var hud = notebook.GetComponent<CheeseHud>();
                if (hud == null) hud = notebook.AddComponent<CheeseHud>();
                if (hud.countText == null)
                    hud.countText = CheeseHud.FindCountText(notebook.transform);
            }
            var ending = notebook != null ? notebook.transform.Find("Ending") : null;
            if (ending != null && ending.GetComponent<EndingController>() == null)
                ending.gameObject.AddComponent<EndingController>();
            WireCheeseSpawner();
        }

